<template>
  <div>
    <!-- 输入框，用于输入 JSON 数据 -->
    <textarea v-model="inputJson" placeholder="请输入 JSON 数据"></textarea>
    <!-- 显示转换错误信息 -->
    <p v-if="errorMessage">{{ errorMessage }}</p>
    <!-- 使用 JsonViewer 组件展示 JSON 数据 -->
    <JsonViewer :value="parsedJson" copyable boxed sort theme="light"/>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue';
import JsonViewer from "vue3-json-viewer";
import "vue3-json-viewer/dist/index.css";

// 存储用户输入的 JSON 数据
const inputJson = ref('');
// 存储解析后的 JSON 对象
const parsedJson = ref(null);
// 存储解析错误信息
const errorMessage = ref('');

// 监听输入框的变化
watch(inputJson, (newValue) => {
  try {
    // 尝试解析输入的 JSON 数据
    parsedJson.value = JSON.parse(newValue);
    console.log(JSON.parse(newValue));
    errorMessage.value = '';
  } catch (error) {
    // 解析失败，显示错误信息
    errorMessage.value = '输入的 JSON 数据格式不正确，请检查。';
    parsedJson.value = null;
  }
});
</script>

<style scoped>
/* 可以添加自定义样式 */
textarea {
  width: 100%;
  height: 200px;
  margin-bottom: 10px;
}
</style>